DROP TABLE IF EXISTS sales_shipment_item; DROP TABLE IF EXISTS sales_shipment; DROP TABLE IF EXISTS customer_contract_price; DROP TABLE IF EXISTS customer_contract; DROP TABLE IF EXISTS inventory_transaction; DROP TABLE IF EXISTS inventory_balance; DROP TABLE IF EXISTS warehouse; DROP TABLE IF EXISTS customer_receipt; DROP TABLE IF EXISTS sales_order_item; DROP TABLE IF EXISTS sales_order; DROP TABLE IF EXISTS product_image; DROP TABLE IF EXISTS sku; DROP TABLE IF EXISTS customer;
CREATE TABLE customer(id BIGINT PRIMARY KEY,customer_code VARCHAR(40),customer_name VARCHAR(200),contact_name VARCHAR(100),phone VARCHAR(40),address VARCHAR(500),business_contact_name VARCHAR(100),business_contact_phone VARCHAR(40),order_contact_name VARCHAR(100),order_contact_phone VARCHAR(40),finance_contact_name VARCHAR(100),finance_contact_phone VARCHAR(40),enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE sku(id BIGINT PRIMARY KEY,product_code VARCHAR(80),sku_code VARCHAR(80),model VARCHAR(100),product_name VARCHAR(200),product_type VARCHAR(30),product_configuration VARCHAR(500),configuration VARCHAR(1000),product_version VARCHAR(80),color VARCHAR(80),lock_body VARCHAR(80),unit VARCHAR(20),current_cost DECIMAL(18,4),factory_price DECIMAL(18,4),enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE product_image(id BIGINT PRIMARY KEY,product_id BIGINT,is_primary BOOLEAN DEFAULT FALSE,sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS customer_fund_account(customer_id BIGINT PRIMARY KEY,balance DECIMAL(19,4) NOT NULL DEFAULT 0);
CREATE TABLE customer_contract(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT,contract_no VARCHAR(80),start_date DATE,end_date DATE,enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS customer_fund_account(customer_id BIGINT PRIMARY KEY,balance DECIMAL(19,4) NOT NULL DEFAULT 0);
CREATE TABLE customer_contract_price(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract_id BIGINT,sku_id BIGINT,sale_price DECIMAL(18,4));
CREATE TABLE sales_order(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_no VARCHAR(50) UNIQUE,external_order_no VARCHAR(100) UNIQUE,customer_id BIGINT,status VARCHAR(40),total_amount DECIMAL(18,2),order_date DATE,order_type VARCHAR(40),salesperson VARCHAR(100),customer_contact VARCHAR(100),customer_phone VARCHAR(60),business_contact_name VARCHAR(100),business_contact_phone VARCHAR(60),order_contact_name VARCHAR(100),order_contact_phone VARCHAR(60),finance_contact_name VARCHAR(100),finance_contact_phone VARCHAR(60),order_remark VARCHAR(1000),delivery_address VARCHAR(1000),delivery_contact VARCHAR(100),delivery_phone VARCHAR(60),shipping_method VARCHAR(100),receipt_confirmed_at TIMESTAMP,shipped_at TIMESTAMP,carrier VARCHAR(100),tracking_no VARCHAR(100),shipping_remark VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,version INT DEFAULT 0);
CREATE TABLE sales_order_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sales_order_id BIGINT,line_no INT,sku_id BIGINT,quantity INT,shipped_quantity INT DEFAULT 0,locked_quantity INT DEFAULT 0,uncovered_quantity INT DEFAULT 0,sale_price DECIMAL(18,2),cost_snapshot DECIMAL(18,4),version INT DEFAULT 0);
CREATE TABLE sales_shipment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shipment_no VARCHAR(50) UNIQUE,sales_order_id BIGINT,delivery_address VARCHAR(500),operator_name VARCHAR(100) NOT NULL,shipped_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,remark VARCHAR(1000));
CREATE TABLE sales_shipment_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sales_shipment_id BIGINT,sales_order_item_id BIGINT,quantity INT);
CREATE TABLE customer_receipt(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sales_order_id BIGINT UNIQUE,amount DECIMAL(18,2),payment_method VARCHAR(40),received_at TIMESTAMP,confirmed_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE warehouse(id BIGINT PRIMARY KEY,warehouse_code VARCHAR(40),warehouse_name VARCHAR(100),is_default BOOLEAN DEFAULT TRUE,enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE inventory_balance(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,warehouse_id BIGINT,sku_id BIGINT,actual_quantity INT DEFAULT 0,locked_quantity INT DEFAULT 0,in_transit_quantity INT DEFAULT 0,version INT DEFAULT 0,UNIQUE(warehouse_id,sku_id));
CREATE TABLE inventory_transaction(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,warehouse_id BIGINT,sku_id BIGINT,transaction_type VARCHAR(40),business_type VARCHAR(40),business_no VARCHAR(80),actual_delta INT,locked_delta INT,transit_delta INT,actual_before INT,actual_after INT,locked_before INT,locked_after INT,transit_before INT,transit_after INT,operated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
